/** Projection modes reserved for 360°/VR playback. */
export type VrProjection = "360" | "stereo" | "none";

/** VR configuration. */
export interface VrOptions {
  readonly projection?: VrProjection;
  readonly fov?: number;
}

/** Returns true when WebXR is available. */
export function isVrSupported(): boolean {
  return typeof navigator !== "undefined" && "xr" in navigator;
}

/**
 * Marks an element as VR-enabled.
 *
 * A future renderer (WebXR / WebGL) will consume these data attributes. The
 * skeleton only reserves the contract so consumers can style and feature-detect.
 */
export function setVrMode(element: HTMLElement, options: VrOptions = {}): void {
  element.dataset.upVr = options.projection ?? "360";

  if (options.fov !== undefined) {
    element.dataset.upVrFov = String(options.fov);
  }
}

/** Clears VR markers from an element. */
export function clearVrMode(element: HTMLElement): void {
  delete element.dataset.upVr;
  delete element.dataset.upVrFov;
}
